code:
int count = 0;
for (int i = 0; i < 3; i++)
{
    for (int j = 0; j < 3; j++)
    {
        if (j == 1)
        {
            break;
        }
        count++;
    }
}
Console.WriteLine(count);

pseudocode:
count ← 0
for (i を 0 から 2 まで 1 ずつ増やしながら)
  for (j を 0 から 2 まで 1 ずつ増やしながら)
    if (j ＝ 1)
      内側の繰返しを終了する  // C#の break（内側のみ）
    endif
    count ← count ＋ 1
  endfor
endfor
count を出力

